"use strict";(globalThis.webpackChunktemp_hub=globalThis.webpackChunktemp_hub||[]).push([[7618],{8341(e,n,t){t.r(n),t.d(n,{assets:()=>l,contentTitle:()=>r,default:()=>h,frontMatter:()=>o,metadata:()=>i,toc:()=>d});const i=JSON.parse('{"id":"Tools/tl300-presentation-creator/pdf502-ai-drivers-license","title":"AI Driver\'s License","description":"---","source":"@site/docs/05-Tools/tl300-presentation-creator/pdf502-ai-drivers-license.md","sourceDirName":"05-Tools/tl300-presentation-creator","slug":"/Tools/tl300-presentation-creator/pdf502-ai-drivers-license","permalink":"/REVA-learning-hub/Tools/tl300-presentation-creator/pdf502-ai-drivers-license","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"AI Driver\'s License","author":"Dr. Sanjay Chitnis","is_presentation":true},"sidebar":"tutorialSidebar","previous":{"title":"AI-Powered Presentation Creator & Interactive Presentation Specification (IPS)","permalink":"/REVA-learning-hub/Tools/tl300-presentation-creator/"},"next":{"title":"Presentation Creator - Technical Architecture","permalink":"/REVA-learning-hub/Tools/tl300-presentation-creator/tl301-presentation-creator-architecture"}}');var s=t(4848),a=t(8453);const o={title:"AI Driver's License",author:"Dr. Sanjay Chitnis",is_presentation:!0},r="PART A: FACILITATION DECK",l={},d=[{value:"MODULE 1: AI and the Future of Learning",id:"module-1-ai-and-the-future-of-learning",level:2},{value:"MODULE 2: AI Literacy for Faculty",id:"module-2-ai-literacy-for-faculty",level:2},{value:"MODULE 3: Designing Lovable Assignments",id:"module-3-designing-lovable-assignments",level:2},{value:"MODULE 4: AI-Resistant to AI-Ready Assessment",id:"module-4-ai-resistant-to-ai-ready-assessment",level:2},{value:"MODULE 5: Designing for Judgment",id:"module-5-designing-for-judgment",level:2},{value:"MODULE 6: Curriculum Design and Institutional Fit",id:"module-6-curriculum-design-and-institutional-fit",level:2},{value:"Introduction",id:"introduction",level:2},{value:"Part 1: Motivation and Engagement",id:"part-1-motivation-and-engagement",level:2},{value:"Self-Determination Theory (Deci &amp; Ryan)",id:"self-determination-theory-deci--ryan",level:3},{value:"Flow Theory (Csikszentmihalyi)",id:"flow-theory-csikszentmihalyi",level:3},{value:"Situated Learning and Legitimate Peripheral Participation (Lave &amp; Wenger)",id:"situated-learning-and-legitimate-peripheral-participation-lave--wenger",level:3},{value:"Interest Development Model (Hidi &amp; Renninger)",id:"interest-development-model-hidi--renninger",level:3},{value:"Part 2: Learning, Memory, and Assessment Design",id:"part-2-learning-memory-and-assessment-design",level:2},{value:"Cognitive Load Theory (Sweller)",id:"cognitive-load-theory-sweller",level:3},{value:"Retrieval Practice (Roediger &amp; Karpicke)",id:"retrieval-practice-roediger--karpicke",level:3},{value:"Desirable Difficulties (Bjork)",id:"desirable-difficulties-bjork",level:3},{value:"Metacognition and Self-Regulated Learning (Flavell; Zimmerman)",id:"metacognition-and-self-regulated-learning-flavell-zimmerman",level:3},{value:"Transfer of Learning",id:"transfer-of-learning",level:3},{value:"Summary Table: Module-to-Theory Cross-Reference",id:"summary-table-module-to-theory-cross-reference",level:2},{value:"A Note on Honest Use of Theory",id:"a-note-on-honest-use-of-theory",level:2}];function c(e){const n={code:"code",em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",hr:"hr",p:"p",pre:"pre",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(n.header,{children:(0,s.jsx)(n.h1,{id:"part-a-facilitation-deck",children:"PART A: FACILITATION DECK"})}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'SLIDE 0.1\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# AI-Ready Educate to Enterprise Faculty Certification Program\n\nDesigning learning experiences for REVA University students to:\n- Promote genuine student learning\n- Prevent cognitive outsourcing to AI\n- Prepare students for AI-era careers\n- Encourage responsible, effective use of AI\n- Strengthen human capabilities that grow MORE valuable because AI exists\n- Overall to support the Educate to Enterprise Philosophy of REVA University\n\n> "The goal is not to stop students from using AI. The goal is to\n>  design learning experiences that develop capabilities becoming\n>  more valuable because AI exists."\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nOpen with this guiding principle before anything else \u2014 it is the\nlens the entire program should be read through. Consider a 60-second\npoll: "In one word, what\'s your biggest fear about AI in your\nclassroom?" Collect answers on a board. Revisit them at the close\nof Module 6 to show which are addressed by the program and which\nremain genuinely open problems worth continued discussion.\n\nADDITIONAL CONTENT PROMPT:\n"Generate a short, warm, one-paragraph welcome script (60-90 words)\nfor a faculty development workshop facilitator to read aloud when\nopening a session on AI in higher education teaching, setting a\ntone that is neither alarmist nor dismissive of AI\'s impact."\n'})}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"module-1-ai-and-the-future-of-learning",children:"MODULE 1: AI and the Future of Learning"}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'SLIDE 1.1\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# Module 1: AI and the Future of Learning\n\nPurpose: Understand why teaching and assessment need redesign \u2014\nnot because AI is bad, but because it changes what is worth\nteaching and how learning can be verified.\n\nBy the end of this module, you will be able to:\n- Identify where AI creates real risk vs. real opportunity in\n  your own course\n- Apply the "Jagged Intelligence" lens to teach verification\n  and judgment\n- Complete a structured Course Audit using the REVA Course\n  Audit Rubric\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nThis module is diagnostic. Faculty should leave with a clear-eyed\nmap of their own course\'s AI exposure \u2014 not a finished solution.\nThe solutions arrive in Modules 3\u20135.\n'})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'SLIDE 1.2\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## 1.1 The Impact of AI \u2014 Where It Already Reaches\n\n- Writing\n- Coding\n- Analysis\n- Design\n- Summarization\n- Content generation\n\nAsk yourself: which of these does my current assessment rely on\nas proof of student learning?\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nHave each faculty member write, on a sticky note, one assessment\nfrom their own course that sits entirely inside one of these six\ncategories. Collect a few examples aloud \u2014 this personalizes the\nlist and sets up the Course Audit exercise later in the module.\n\nADDITIONAL CONTENT PROMPT:\n"Generate 6 short, discipline-neutral real-world anecdotes (2-3\nsentences each) illustrating a professional in [Engineering /\nBusiness / Science / Humanities] whose routine work in [writing /\ncoding / analysis / design / summarization / content generation]\nwas recently reshaped by AI tools. Keep tone factual and current,\navoid naming specific commercial products, suitable for a faculty\nworkshop slide."\n'})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'SLIDE 1.3\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## 1.2 Opportunities\n\n- Personalized learning \u2014 pacing and support adapted per student\n- Higher productivity \u2014 less time on low-value mechanical work\n- Accessibility \u2014 translation, text-to-speech, format conversion\n  for diverse learners\n- Rapid prototyping \u2014 ideas tested and iterated faster\n\nThis module is not only about risk. AI opens real teaching\nopportunities too.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nAsk: "Has anyone already used AI to help a struggling student in\na way that would not have been possible before?" Surface a genuine\npositive story if one emerges \u2014 it balances the room before the\nrisk slide that follows.\n\nADDITIONAL CONTENT PROMPT:\n"Generate 3 short, realistic vignettes (3-4 sentences each) of a\nfaculty member using AI to support a struggling or differently-abled\nstudent in a higher education setting \u2014 one on personalized pacing,\none on accessibility (language or format), one on rapid feedback.\nIndian higher-education context, no named tools or brands."\n'})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"SLIDE 1.4\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## 1.3 Risks\n\n- AI Slop \u2014 low-effort, low-value output that looks finished\n- Cognitive dependency \u2014 skipping the struggle that builds capability\n- Surface learning \u2014 pattern-matching without understanding\n- Reduced originality \u2014 convergence toward the same AI-typical answers\n\nNone of these are solved by banning AI. They are solved by\nredesigning what we ask students to produce, and how we verify it.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nState explicitly: a course that bans AI entirely can still produce\ncognitive dependency (on notes, on rote memorization) and surface\nlearning. This reframes the entire certification program's premise\nbefore Module 3 begins.\n\nADDITIONAL CONTENT PROMPT:\n\"Generate 2 short, realistic before/after examples of student\nwritten work: a 'AI slop' version (fluent but generic, low\noriginality, no local grounding) and a genuinely strong version of\nthe same assignment prompt, for the topic of [renewable energy /\nsupply chain management / water conservation]. Keep each under 80\nwords so both fit on one comparison slide.\"\n"})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"SLIDE 1.5\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## 1.4 Jagged Intelligence\n\nIn the same conversation, AI can be:\n- Brilliant\n- Incorrect\n- Creative\n- Irrational\n\nThere is no reliable way to predict which mode you will get\nwithout checking. Verification and judgment are no longer optional\nadd-ons \u2014 they are now core disciplinary skills, for faculty and\nstudents alike.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nLive-demo if possible: ask an AI tool a question in your own\ndiscipline where you already know the correct answer, in front of\nthe room, and see what comes back. A wrong or partially wrong\nanswer is a better teaching moment than any slide. Jagged\nIntelligence is the argument for why Module 4's verification-based\nassessment design exists \u2014 plant that seed here.\n\nADDITIONAL CONTENT PROMPT:\n\"Generate 3 short example AI-generated responses (2-4 sentences\neach) for the discipline of [Engineering / Business / Science],\nwhere the response is fluent, confident, and PARTIALLY correct but\ncontains one subtle factual or logical error suitable for a live\n'spot the mistake' exercise with faculty. Include the corrected\nversion separately, not visible on the slide.\"\n"})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'SLIDE 1.6\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## 1.5 The AI Divide \u2014 Four Dimensions of Access\n\nNot a simple "included vs. excluded." A student can be included\non some dimensions and excluded on others:\n\n- Motivational access \u2014 does the student want to engage with AI,\n  or actively avoid/distrust it?\n- Material access \u2014 reliable device, data, electricity\n- Skills access \u2014 knows how to prompt, verify, iterate\n- Usage access \u2014 is actually permitted or encouraged to use AI in\n  their own context (home, hostel, classroom norms)\n\nAssuming uniform access across a socioeconomically mixed student\nbody will systematically disadvantage some students in AI-based\nassignments.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nAsk faculty: "Of your current class, do you actually know which\nstudents have reliable data or device access after 9pm?" Most\nwill not. Flag this as something the Course Audit should surface\nexplicitly, not assume away.\n\nADDITIONAL CONTENT PROMPT:\n"Summarize, in 3-4 factual bullet points suitable for a faculty\nslide, recent publicly available statistics on smartphone and\ninternet access disparities among Indian higher-education students\nby geography (urban/rural) and gender. Cite general sources, no\nspeculation, keep politically neutral and non-alarmist in tone."\n'})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"SLIDE 1.7\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## 1.6 Preparing Consumers, Creators, and Orchestrators\n\nHigher education must decide what it is preparing students to be:\n- AI consumers \u2014 use existing tools as given\n- AI creators \u2014 build new AI-powered solutions\n- AI orchestrators \u2014 direct AI systems and workflows toward goals\n\nREVA's AI Ascent framework (Consumer \u2192 Creator \u2192 Builder \u2192\nOrchestrator \u2192 Researcher) maps this progression across a full\ndegree program. See the AI Ascent materials for the complete\nmodel and how individual courses map onto it.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nKeep this slide brief \u2014 its purpose is to connect faculty to the\none canonical progression model used across REVA, not to re-teach\nit from scratch.\n"})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"SLIDE 1.8\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## Faculty Activity: Course Audit\n\nUsing the REVA Course Audit Rubric (handout), classify each major\nassessment in one of your courses:\n\n- AI-Vulnerable \u2014 fully outsourceable to AI as currently designed\n- AI-Resistant \u2014 difficult, though not impossible, to outsource\n- AI-Ready \u2014 already requires genuine human-AI collaboration\n\nFor each AI-Vulnerable item, note:\n- Which Risk (Slide 1.4) does it expose you to?\n- Which AI Divide dimension (Slide 1.6) would affect fairness if\n  you redesigned it to require AI use?\n\nKeep this rubric \u2014 you will use the same categories again in\nModule 6 and in your Capstone submission.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nDistribute the rubric as a physical or shared-document handout that\nfaculty keep for the rest of the program. Have pairs cross-check\none classification each \u2014 a low-cost early habit in rater\nconsistency that pays off in Module 4.\n\nADDITIONAL CONTENT PROMPT:\n\"Generate a one-page printable worksheet template for a 'Course\nAudit', with columns for: Assessment Name, Current Format,\nClassification (AI-Vulnerable / AI-Resistant / AI-Ready), Risk\nExposed, AI Divide Dimension Affected, and Redesign Priority\n(P1/P2/P3). Plain text table format suitable for conversion to a\nprintable handout.\"\n"})}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"module-2-ai-literacy-for-faculty",children:"MODULE 2: AI Literacy for Faculty"}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'SLIDE 2.1\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# Module 2: AI Literacy for Faculty\n\nGoal: Use AI intelligently \u2014 neither fearing it nor trusting it\nblindly. This module builds the working knowledge that Modules\n3\u20136 assume you already have.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nPosition this as infrastructure for what follows, not a standalone\n"tech literacy" session. This is a specific kind of literacy \u2014\nverification, evaluation, disclosure \u2014 not general tool familiarity.\n'})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'SLIDE 2.2\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## Understanding AI \u2014 The Landscape\n\n- LLMs \u2014 large language models, the technology behind most tools\n  you and your students will encounter\n- Multimodal AI \u2014 models handling text, image, audio, and video\n  together\n- Agents \u2014 AI systems that take multi-step actions, not just\n  answer single questions\n- AI ecosystems \u2014 how these pieces increasingly connect and act\n  on your behalf\n\nYou do not need to be a technical expert. You need enough of a\nworking model to reason about what is plausible for AI to do in\nyour discipline.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nKeep this brief and non-technical. If deep technical questions\narise, park them for an optional follow-up session rather than\nslowing the room.\n\nADDITIONAL CONTENT PROMPT:\n"Generate 4 short, non-technical analogies (one sentence each)\nexplaining LLMs, multimodal AI, agents, and AI ecosystems to a\nnon-computer-science faculty audience, using everyday objects or\nprocesses as comparisons (avoid technical jargon entirely)."\n'})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'SLIDE 2.3\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## Hallucinations \u2014 Confidently Wrong\n\nAI may generate, with full apparent confidence:\n- Incorrect facts\n- Fake references and citations\n- Imaginary sources that look completely real\n\nThe same system that is brilliant on one question can fabricate\nconvincingly on the next, with no visible warning sign.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nLive demo works well here \u2014 ask for a citation or reference in\nyour own discipline and check whether it is real, on the spot.\nThis is often the most convincing moment in the workshop for\nskeptical faculty.\n\nADDITIONAL CONTENT PROMPT:\n"Generate 2 examples of a plausible-sounding but entirely\nfabricated academic citation (author, year, journal, title) in the\nfield of [Engineering / Computer Science / Management], formatted\nexactly as a real citation would appear, for use in a faculty\nworkshop demonstrating AI hallucination. Clearly label these as\nFABRICATED in the facilitator\'s separate answer key, not on the\nslide shown to participants."\n'})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'SLIDE 2.4\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## Automation Bias\n\nHumans systematically over-trust automated and algorithmic output\n\u2014 even experts, even when they know the system is imperfect.\n\nThis is not only a student problem. Faculty are equally susceptible\nwhen grading or research-assisting with AI.\n\nDiscussion: has AI output ever seemed "obviously right" to you\nbecause it was fluent and confident \u2014 before you actually checked it?\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nInclude faculty in the risk, not just students \u2014 this builds\ncredibility and models the humility you want them to teach.\n\nADDITIONAL CONTENT PROMPT:\n"Provide a brief, plain-language, one-paragraph summary of the\nwell-established psychological phenomenon of automation bias,\nsuitable for a non-specialist faculty audience, referencing the\ngeneral research area without inventing specific fake study\ncitations."\n'})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"SLIDE 2.5\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## Prompt Engineering \u2014 A Dialogue, Not a Single Shot\n\nStarting template:\nRole + Context + Task + Constraints + Format\n\nReal prompting is iterative:\n1. Draft a prompt using the template\n2. Read the output critically\n3. Refine \u2014 add missing context, tighten constraints, ask for a\n   different angle\n4. Repeat until the output actually meets the need\n\nStep 1 is a starting scaffold. Steps 2\u20134 are the actual skill.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nEmphasize that stopping at step 1 teaches a false idea of what\ngood AI use looks like. If time allows, have faculty pairs run a\nreal 3-round refinement live and compare the first output to the\nfinal one.\n\nADDITIONAL CONTENT PROMPT:\n\"Generate one example 3-round prompt refinement sequence for the\ntask 'write a project brief for a final-year engineering capstone\nproject on solar-powered water pumps' \u2014 show the initial one-shot\nprompt, a short critique of its output's weaknesses, a refined\nsecond prompt, and a further refined third prompt, so faculty can\nsee the iteration process modeled step by step.\"\n"})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"SLIDE 2.6\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## Evaluating AI Output \u2014 A Durable Method\n\nFor any AI output, from any tool, check:\n- Accuracy \u2014 is it actually correct? Verify independently.\n- Completeness \u2014 what is missing that a full answer would include?\n- Creativity \u2014 is this a genuinely novel angle, or the most\n  statistically likely answer?\n- Reliability \u2014 would this hold up if you asked the same question\n  three different ways?\n\nThis method outlasts any single tool. Apply it to whatever AI\ntools you currently use.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nIf you want a live exercise, have faculty run the same prompt\nthrough whatever tools they have access to and apply this four-part\ncheck to each output.\n\nADDITIONAL CONTENT PROMPT:\n\"Generate one sample AI-written answer (150-200 words) to the\nquestion 'Explain the causes of urban flooding,' along with a\ncompleted four-part evaluation (Accuracy, Completeness, Creativity,\nReliability) applied to that sample answer, to model what a\ncompleted evaluation looks like before faculty attempt one\nthemselves.\"\n"})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"SLIDE 2.7\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## Ethics in Practice \u2014 Two Scenarios\n\nScenario A \u2014 Intellectual Property\nA student submits code where a large, functioning chunk was\nAI-generated verbatim, undisclosed. Is this different from copying\na chunk from an online forum, undisclosed? What makes it the same\nor different?\n\nScenario B \u2014 Privacy\nA faculty member pastes a student's exam answer, including their\nname, into a public AI chatbot to check for plagiarism patterns.\nWhat is the actual privacy exposure here, and what should have\nbeen done instead?\n\nDiscuss in pairs: what policy would prevent each scenario, and\nwhere should that policy live?\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nScenario B is deliberately about faculty behavior, not only\nstudent behavior. Bias and transparency can be woven into\ndiscussion naturally \u2014 ask \"where is the bias risk in Scenario A?\"\n(whose coding style or idiom gets flagged as 'suspicious' versus\n'normal' by a pattern-detection tool) as a natural extension.\n\nADDITIONAL CONTENT PROMPT:\n\"Generate 2 additional short ethics scenarios (3-4 sentences each)\nfor a faculty workshop on AI in higher education: one focused on\nbias (an AI grading assistant scoring differently based on writing\nstyle associated with non-native English speakers) and one focused\non transparency (a university dashboard using AI to flag 'at risk'\nstudents without disclosing the criteria to the students\nthemselves). Keep each scenario open-ended, without a stated\nresolution, to prompt discussion.\"\n"})}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"module-3-designing-lovable-assignments",children:"MODULE 3: Designing Lovable Assignments"}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"SLIDE 3.1\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# Module 3: Designing Lovable Assignments\n\nCore principle: Students learn more deeply when they enjoy\nmeaningful work \u2014 and they will do it themselves rather than\ndelegate to AI, because delegating would mean missing out on\nsomething they actually want to do.\n\nTwo different defenses against AI outsourcing exist side by side\nin this program:\n- LOVABLE (this module) \u2014 psychological: why would I skip the\n  part I enjoy?\n- AI-Resistant / AI-Proof design (Module 4) \u2014 structural: the\n  task cannot be skipped and still pass\n\nBoth matter. Neither replaces the other.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nWrite both defense types on the board and leave them visible for\nthe rest of the module \u2014 this distinction prevents faculty from\nseeing Module 3 and Module 4 as redundant or competing.\n"})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"SLIDE 3.2\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## The LOVABLE Framework\n\n- L \u2014 Learner Agency: the student chooses direction or approach\n- O \u2014 Originality: the output cannot be a template fill-in\n- V \u2014 Voice: the student's own perspective is visible in the result\n- A \u2014 Authentic Audience: someone real, beyond the grader, will see it\n- B \u2014 Build/Create: the student makes something, not just explains it\n- L \u2014 Local Context: grounded in a real, nearby, tangible problem\n- E \u2014 Engagement: the task holds attention because it genuinely matters\n\nThe two L's are distinct. Learner Agency is about whose CHOICE the\nassignment reflects. Local Context is about whose PROBLEM it is.\nAn assignment can have one without the other.\n\nSee the Theoretical Foundations Appendix for the research base\nbehind this framework (Self-Determination Theory, Flow Theory,\nSituated Learning, Interest Development).\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nState the two-L distinction aloud, do not leave it only on the\nslide. Ask faculty for a quick example of an assignment with\nagency but not local context (e.g., \"pick any topic you like,\"\nwith no real-world grounding), and one with local context but not\nagency (e.g., \"analyze this specific local case study,\" with no\nchoice in approach). This cements the distinction quickly.\n\nADDITIONAL CONTENT PROMPT:\n\"Generate a short, light, faculty-friendly meme concept (image\ndescription + caption text, no actual image) contrasting a\n'traditional assignment' with a 'LOVABLE assignment' \u2014 tone should\nbe gently humorous, workplace-appropriate, suitable for a higher-ed\nfaculty workshop slide. Provide 2 variations.\"\n"})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'SLIDE 3.3\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## Worked Example\n\nTraditional:\n"Explain the Internet of Things."\n\nRedesigned:\n"Design and pitch an IoT solution for water scarcity in your\nlocality."\n\nWhat changed:\n- Learner Agency \u2014 student picks the specific water problem\n- Local Context \u2014 their own neighborhood or area\n- Authentic Audience \u2014 a real pitch, not just a submission\n- Build/Create \u2014 a solution, not an explanation\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nWalk through which LOVABLE letters this example hits, as shown \u2014\nfaculty should see the framework applied, not just asserted.\n'})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'SLIDE 3.4\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## A Technical Worked Example\n\nTraditional:\n"Implement a hash table."\n\nRedesigned:\n"Build a duplicate-file finder for your own Downloads folder using\na hash-based approach. Present your before-and-after storage\nsavings to a classmate \u2014 did their file types behave differently\nthan yours?"\n\nWhat changed:\n- Build/Create \u2014 a working tool, not a textbook implementation\n- Local Context \u2014 their own actual machine and files\n- Authentic Audience \u2014 a real peer, a real comparison\n- Voice \u2014 their own choice of what counts as "duplicate" for their\n  own file types\n\nLOVABLE design applies as well to a data-structures course as it\ndoes to a humanities or business course.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nIf faculty from technical departments are in the room, ask them\nto sketch one more example live before moving on.\n\nADDITIONAL CONTENT PROMPT:\n"Generate 2 more technical LOVABLE-style assignment examples (in\nthe same traditional/redesigned/what-changed format) for the\ndisciplines of Electronics and Mechanical Engineering, grounded in\na plausible local Bengaluru context (e.g., traffic, water supply,\nelectricity load), suitable for a faculty workshop slide."\n'})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'SLIDE 3.5\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## More Assignment Genre Examples\n\n- Podcast Interview\n- Future News Report\n- Escape Room Design\n- Historical Instagram Takeover\n- Meme Creation\n- Animation Creation\n- Debate and Role Play\n- Comic Strip Summary\n- Shark Tank Idea Pitch\n\nUse the technical example (Slide 3.4) as your model for adapting\nthis same logic to a quantitative or highly technical discipline.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nBrainstorm exercise: faculty individually pick one genre from this\nlist and one concept from their own course, and sketch a one-line\nredesigned assignment in 3 minutes, then share with a neighbor.\n\nADDITIONAL CONTENT PROMPT:\n"Generate 5 additional LOVABLE-style assignment genre ideas beyond\nthe list already given (podcast, news report, escape room,\nInstagram takeover, meme, animation, debate, comic strip, Shark\nTank pitch), suitable for higher-education students across\nEngineering, Business, and Science disciplines. One line each,\ngenre name plus a one-sentence description."\n'})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'SLIDE 3.6\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## A Note on Rigor\n\nA fun assignment is not automatically a rigorous one. Enjoyment\nand learning depth are related but not identical.\n\nBefore finalizing a LOVABLE-redesigned assignment, ask:\n- Does this still require the core disciplinary skill the original\n  assignment tested?\n- Could a student complete this successfully while missing the\n  actual learning objective?\n\nLOVABLE and AI-Resistant/Proof design (Module 4) work together \u2014\none makes the work worth doing, the other ensures it is still\nworth grading.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nWithout this guardrail, faculty may over-index on "fun" and drift\ntoward engagement-as-entertainment. Close with a short individual\nreflection: faculty check their Slide 3.5 sketch against these two\nquestions before the module ends.\n\nADDITIONAL CONTENT PROMPT:\n"Generate a short 4-question self-check worksheet faculty can use\nafter designing any LOVABLE assignment, to verify the assignment\nstill tests the intended disciplinary skill and has not drifted\ninto pure entertainment. Plain text, printable format."\n'})}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"module-4-ai-resistant-to-ai-ready-assessment",children:"MODULE 4: AI-Resistant to AI-Ready Assessment"}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'SLIDE 4.1\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# Module 4: Designing Assessment That Cannot Simply Be Outsourced\n\nPurpose: Design assessment that verifies genuine learning \u2014 not\nassessment that is theoretically "unbeatable," but assessment\nwhere outsourcing is either impractical, detectable, or\npedagogically self-defeating.\n\nBy the end of this module, you will be able to:\n- Place any assessment on the AI-Resistant \u2192 AI-Proof \u2192 AI-Ready \u2192\n  AI-Native spectrum\n- Design a scalable, multi-tier verification process for your\n  own assessments\n- Explain the validity/reliability trade-offs of performance-based\n  assessment, and how to manage them\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nSet expectations early: no assessment is literally impossible to\noutsource. The goal is to make outsourcing hard enough, detectable\nenough, or pointless enough that a student is better off doing the\nwork themselves. This module gives you a spectrum and a mechanism,\nnot a guarantee.\n'})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'SLIDE 4.2\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## A Spectrum, Not a Single Label\n\n- AI-Resistant \u2014 difficult to outsource; requires real effort to\n  fake convincingly\n- AI-Proof \u2014 very hard to outsource without direct, observable\n  human performance\n- AI-Ready \u2014 designed assuming AI collaboration; the task requires\n  human judgment ON TOP of AI assistance\n- AI-Native \u2014 an entire course or curriculum assumes AI\n  participation throughout, not just in individual tasks\n\nMost of your existing assessments can be moved one step up this\nspectrum without a complete redesign.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nAvoid the word "proof" implying certainty \u2014 even a viva can be\ngamed by a memorized script. Frame this as a spectrum of increasing\ndifficulty and decreasing payoff for outsourcing, not an absolute\nguarantee. This framing keeps the module honest and credible.\n'})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"SLIDE 4.3\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## Four Assessment Approaches\n\nObservation-Based\n- Laboratories, field visits, site studies, internship tasks\n\nPerformance-Based\n- Viva, presentation, debate, demonstration\n\nProcess-Based\n- Draft reviews, learning journals, design iterations, reflection logs\n\nContext-Based\n- Local interviews, community projects, field data collection,\n  proprietary datasets\n\nEach approach shifts what is being verified: not just the final\nanswer, but the process, the performance, or the setting that\nproduced it.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nAsk faculty to identify, for their own course, one assessment that\ncould move from a pure written submission into one of these four\ncategories without changing the underlying learning objective.\n"})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'SLIDE 4.4\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## Discipline Transformations\n\nEngineering\nInstead of: "Write code."\nUse: "Defend your algorithm choices in a viva."\n\nBusiness\nInstead of: "Write a marketing plan."\nUse: "Interview real local businesses and base your plan on what\nyou find."\n\nScience\nInstead of: "Submit a lab report."\nUse: "Analyze a deliberately flawed experiment and identify what\nwent wrong."\n\nNotice: the underlying skill being tested does not change. What\nchanges is how it is verified.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nHave faculty attempt this same transformation for one assessment\nin their own discipline right now, in pairs, before moving to the\nverification mechanism on the next slides.\n\nADDITIONAL CONTENT PROMPT:\n"Generate 4 additional discipline-specific \'instead of / use\'\nassessment transformation examples, one each for Computer Science,\nArchitecture, Pharmacy, and Law, in the same short two-line format\nas the Engineering/Business/Science examples already given, suitable\nfor a faculty workshop slide."\n'})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"SLIDE 4.5\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## The Validity and Reliability Problem\n\nPerformance-based assessment (viva, presentation, demonstration) is\nharder to fake \u2014 but introduces new problems:\n\n- Rater consistency \u2014 will two faculty score the same viva the\n  same way?\n- Time cost \u2014 a 15-minute viva per student does not scale to a\n  200-student cohort\n- Fairness \u2014 confidence, accent, and communication style can\n  distort scoring independent of actual understanding\n\nMoving to performance-based assessment without addressing these\nissues trades one validity problem for another.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nDo not skip this slide or treat it as a footnote \u2014 this is the\nsingle biggest reason faculty resist performance-based assessment,\nand dismissing the concern will cost you credibility in the room.\nAcknowledge it fully before presenting the solution.\n"})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"SLIDE 4.6\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## The Tiered Verification Model\n\nA three-tier structure that scales fairness and rigor together:\n\nTier 1 \u2014 Self-Assessment (100% of students)\nEvery student scores their own submission against the course\nrubric before submitting. Cheap, catches the weakest cases early,\nand creates a record of the student's own thinking.\n\nTier 2 \u2014 AI-Conducted Viva (100% or most students)\nAn AI system asks 3\u20135 follow-up questions generated specifically\nfrom THIS student's submission \u2014 not from a fixed question bank.\nThis checks understanding beyond the static submission, at a scale\nno faculty member could match alone.\n\nTier 3 \u2014 Expert Viva (a defined subset only)\nReserved for: students flagged by Tier 2 as inconsistent or\nborderline, students seeking top-band or portfolio-grade\ncredentialing, and a random audit sample for quality assurance.\n\nFaculty time is spent where it matters most \u2014 not spread evenly\nregardless of stakes.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nThis is the core mechanism of the entire module \u2014 spend the most\ntime here. Make the trigger criteria for Tier 3 explicit and public\nfrom day one (for example: bottom 15% and top 15% of Tier 2 scores,\nplus a 10% random audit) so students see the system as transparent,\nnot arbitrary. On a 10% sample of Tier 3 vivas, have two faculty\nindependently score the same session and compare \u2014 this catches\nrater drift early and cheaply.\n\nSafeguard to raise explicitly: what stops a student from having\nanother AI answer the Tier 2 viva questions for them in real time?\nMitigations include synchronous, camera-on delivery, and questions\ngenerated live rather than drawn from any reusable bank.\n"})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'SLIDE 4.7\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## Why This Concentrates Rigor Where It Is Needed\n\nRater inconsistency matters most at the edges of a grade\ndistribution \u2014 borderline pass/fail, and borderline top marks.\nTier 3 concentrates expert human attention exactly there.\n\nThe middle of the distribution, where the consequences of small\nscoring differences are lower, is handled by Tiers 1 and 2.\n\nThis is a deliberate, risk-based allocation of your most limited\nand valuable resource: expert faculty time.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nThis slide is the "why it works" explanation for skeptical faculty\nwho understand assessment theory \u2014 useful to have ready if\nquestioned, but can be skipped in a time-constrained session\nwithout losing the practical mechanism.\n'})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'SLIDE 4.8\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## Faculty Activity: Redesign One Assessment\n\nTake one assessment from your Module 1 Course Audit marked\n"AI-Vulnerable."\n\n1. Move it one step along the AI-Resistant \u2192 AI-Proof \u2192 AI-Ready\n   spectrum\n2. Choose which of the four approaches (observation / performance /\n   process / context-based) fits best\n3. Sketch a Tier 1 / Tier 2 / Tier 3 structure for it \u2014 even roughly\n4. Identify your Tier 3 trigger criteria\n\nBring this draft to your peer-review pod before the Pilot phase.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nThis activity output feeds directly into the Faculty Capstone \u2014\ntreat it as a live first draft, not a throwaway exercise.\n'})}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"module-5-designing-for-judgment",children:"MODULE 5: Designing for Judgment"}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"SLIDE 5.1\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# Module 5: Designing for Judgment\n\nPhilosophy: Do not prohibit AI. Teach students to collaborate with\nit intelligently \u2014 knowing what to hand to AI, and what to keep\nfor themselves.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nThis module builds directly on Module 4's mechanism and Module 3's\nmotivation \u2014 assignments here should assume both a reason to want\nto do the work (Module 3) and a way to verify it was actually done\n(Module 4).\n"})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'SLIDE 5.2\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## Shift Up and Left\n\nTwo questions define where any task sits:\n\nVertical axis \u2014 What altitude is this work?\n- Entry-level / individual contributor: routine execution\n- Leadership level: judgment under ambiguity, prioritization,\n  accountability for trade-offs\n\nHorizontal axis \u2014 Where in the work lifecycle does this sit?\n- Execution: doing the defined task\n- Origination: deciding what the task should even be\n\nAI is strongest at the bottom-right of this space \u2014 routine\nexecution of defined tasks. Curriculum should pull students toward\nthe top-left: origination and judgment, earlier than they would\nnormally be exposed to it.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nUse your own institution\'s reporting hierarchy as the anchor for\nthe vertical axis \u2014 most faculty immediately understand "what a\nteam lead does that a fresh hire does not," and this makes the\nabstract axis concrete without further explanation.\n'})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'SLIDE 5.3\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## The Quadrant, Illustrated\n\n                 ORIGINATION <-------\x3e EXECUTION\n  LEADERSHIP    +-------------------------+-------------------------+\n  (Judgment)    |      TARGET ZONE        |                         |\n                |                         |                         |\n                | "Our system is slow \u2014   | "Optimize this query,   |\n                |  decide what to         |  justify the trade-offs |\n                |  investigate and why"   |  you made"              |\n                +-------------------------+-------------------------+\n  ENTRY LEVEL   |                         |   HIGHEST AI            |\n  (Routine)     | Defined problem, still  |   SUBSTITUTION RISK     |\n                | executed mechanically   |                         |\n                |                         | "Write a sorting        |\n                |                         |  function" (unmodified) |\n                +-------------------------+-------------------------+\n\nCurriculum goal: move assignments toward the top-left over the\ncourse of a program \u2014 not by removing execution, but by wrapping\nit in origination and judgment.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nHave faculty plot one of their own existing assignments onto this\ngrid, then plot a redesigned version of the same assignment moved\none step toward the target zone. This is the single most useful\ndiagnostic exercise in the module.\n'})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'SLIDE 5.4\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## Human and AI Responsibilities\n\nHuman responsibilities\n- Purpose\n- Values\n- Decision-making\n- Critical evaluation\n\nAI responsibilities\n- Drafting\n- Research support\n- Idea generation\n- Analysis\n\nThe design question for every assignment: which of these am I\nactually asking the student to demonstrate?\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nKeep this simple and use it as a quick-check tool \u2014 before\nfinalizing any AI-Ready assignment, faculty should be able to\npoint to which "human responsibility" box the assignment is really\ntesting.\n'})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"SLIDE 5.5\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## The AI-Ready Assignment Canvas\n\nFor any assignment, answer five questions:\n\n- Problem \u2014 What issue is being addressed?\n- Human Skills \u2014 What capabilities are targeted?\n- AI Support \u2014 How may AI be used?\n- Evidence \u2014 How will human thinking be demonstrated?\n- Deliverable \u2014 What must be submitted?\n\nUse this canvas as your starting template for every redesigned\nassignment in this module and in your Capstone.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nThis canvas is the most reusable tool in the entire program \u2014\nprint it as a one-page worksheet faculty can fill in for any\nassignment, not just the samples on the following slides.\n"})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"SLIDE 5.6\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## Sample AI-Ready Assignments\n\nFake News Generator and Debunker\nGenerate misinformation, then systematically expose it.\n\nScenario Planning\nCreate future scenarios for water shortages, climate adaptation,\nor urban transport.\n\nShark Tank Simulation\nBuild AI-supported startup proposals.\n\nReverse Engineering\nStudy a product's design, manufacturing, sustainability, and\nbusiness model.\n\nAudience Shifting\nExplain one concept to a school student, an undergraduate, an\nindustry professional, and a researcher \u2014 four different versions.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nNote that Audience Shifting is a particularly strong AI-Ready task\nbecause it forces the student to judge what changes across\naudiences \u2014 something AI can draft but cannot decide on its own.\n"})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'SLIDE 5.7\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## A Technical AI-Ready Example\n\nAI generates a sorting or searching algorithm with a subtle,\ndeliberately embedded flaw.\n\nStudents must:\n1. Diagnose the flaw \u2014 not just notice something is wrong, but\n   explain precisely why it is wrong\n2. Correct it\n3. Extend the corrected version to handle a harder case\n\nThis treats AI as a genuinely imperfect collaborator \u2014 consistent\nwith Jagged Intelligence (Module 1) \u2014 rather than assuming AI\noutput is always a clean starting draft.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nThis example exists specifically to show that AI-Ready design\nworks in highly technical, proof-based disciplines, not only in\nopen-ended or communication-heavy ones.\n\nADDITIONAL CONTENT PROMPT:\n"Generate 3 short code snippets (in Python or C, 10-15 lines each)\nimplementing a common algorithm (e.g., binary search, bubble sort,\na basic linked-list insert) each containing exactly one subtle,\nrealistic bug of the kind an AI code generator might plausibly\nintroduce. Provide the flawed version for the student-facing slide\nand a separate corrected version with an explanation for the\nfacilitator\'s answer key."\n'})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"SLIDE 5.8\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## The Mother of All Assignments\n\nThe most ambitious task in this program. Students:\n\n1. Design an examination paper for a topic of their choice\n2. Benchmark it against a comparable course or curriculum elsewhere\n3. Use AI responsibly throughout the process\n4. Solve the paper themselves\n5. Document their thinking at every step\n\nThis assignment sits firmly in the top-left of the Shift Up and\nLeft quadrant \u2014 maximum origination, maximum judgment.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nTreat this as a capstone-level task within a course, not a routine\nassignment \u2014 it typically requires its own dedicated rubric and a\nlonger timeline than a standard assignment. Consider using it as\none of the required Faculty Capstone deliverables rather than a\nweekly task.\n\nADDITIONAL CONTENT PROMPT:\n\"Generate a detailed worked exemplar of 'The Mother of All\nAssignments' for an undergraduate Data Structures course: a sample\nstudent-designed exam question, a brief benchmark comparison\nagainst a named international course syllabus, the student's own\nworked solution, and a short reflection log entry documenting\ntheir AI usage at each of the five steps.\"\n"})}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"module-6-curriculum-design-and-institutional-fit",children:"MODULE 6: Curriculum Design and Institutional Fit"}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"SLIDE 6.1\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# Module 6: Curriculum Design and Institutional Fit\n\nPurpose: Assignment redesign alone is not enough. This module\naddresses whole-course and whole-curriculum redesign, and connects\nyour classroom decisions to REVA's institutional AI usage policy.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nThis module closes the loop from individual assignments (Modules\n3\u20135) to full courses and, eventually, to REVA's broader strategy.\n"})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'SLIDE 6.2\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## Three Categories of Skills\n\nHuman-Only Skills\nLeadership, ethics, empathy, negotiation, entrepreneurship,\ncritical thinking, systems thinking, sensemaking, ethical\nreasoning, communication, interdisciplinary problem solving\n\nHuman + AI Skills\nResearch, design, innovation, consulting, analysis\n\nAI-Assisted Skills\nCoding, drafting, documentation, information retrieval\n\nEvery Course Learning Outcome (CLO) in your course belongs in one\nof these three categories.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nThis category list consolidates what were previously two separate\nlists into one \u2014 treat "Human-Only Skills" as the complete set of\ndurable human capabilities, not as a short list to which more\nitems get appended elsewhere.\n'})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"SLIDE 6.3\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## Curriculum Mapping Exercise\n\nTag every CLO in your course as Human-Only, Human + AI, or\nAI-Assisted.\n\nThen, for each tag, decide what actually changes:\n- Human-Only CLOs \u2014 should be assessed through performance-based\n  or process-based methods (Module 4), never through a format AI\n  could complete unsupervised\n- Human + AI CLOs \u2014 should require the AI-Ready Assignment Canvas\n  (Module 5) to make the collaboration explicit\n- AI-Assisted CLOs \u2014 may allow full AI use, disclosed, with\n  assessment focused on the quality of oversight and verification\n\nTagging without a consequence is just paperwork. Each tag should\nchange how you teach and assess that outcome.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nThis is the direct fix to a gap raised during program design \u2014\nclassification alone accomplishes nothing if it does not change\nwhat happens next. Push faculty to write down, for at least one\nCLO, exactly what will be different in their syllabus because of\nthis tag.\n"})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"SLIDE 6.4\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## AI Usage Policy Zones\n\nGreen Zone \u2014 Freely Allowed\nBrainstorming, research support, idea generation, outlining\n\nYellow Zone \u2014 Allowed With Disclosure\nCoding, drafting, analysis, design support\n\nRed Zone \u2014 Not Allowed\nClosed-book exams, viva, oral defense, in-class writing\n\nEvery assignment and assessment in your course should have an\nexplicit, stated zone. Students should never have to guess.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nState this zone explicitly on every assignment brief and every\nexam paper going forward \u2014 ambiguity here is one of the most\ncommon sources of academic integrity disputes.\n"})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"SLIDE 6.5\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## Disclosing AI Use \u2014 A Ready-Made Mechanism\n\nFor any Yellow Zone task, students complete a short, structured\nAI Usage Declaration alongside their submission:\n\n- Which tool(s) were used\n- For which part of the task\n- What was kept, changed, or discarded from the AI's output\n- A brief statement of what the student verified independently\n\nThis is not a new form to invent \u2014 REVA already has a working\ndeclaration mechanism aligned to current published research\nstandards for AI usage disclosure. Use it as-is.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nPoint faculty directly to REVA's existing guide-llm-declaration\ntool here rather than asking them to design their own disclosure\nform \u2014 this saves significant Module 6 preparation time and keeps\ndisclosure format consistent across departments.\n"})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'SLIDE 6.6\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## The REVA Assignment Rubric\n\n| Criterion | Weight |\n|---|---|\n| Domain Knowledge | 30% |\n| Problem Solving | 20% |\n| Creativity | 15% |\n| AI Usage Quality | 15% |\n| Critical Evaluation of AI | 10% |\n| Reflection | 10% |\n\nThis rubric already captures your program\'s key success measures\n\u2014 "Creativity" and "Critical Evaluation of AI" are not just grading\ncriteria, they are your evidence for institutional reporting on\nstudent-level outcomes.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nEmphasize that this single rubric, applied consistently, generates\nthe data needed later for institutional review \u2014 faculty do not\nneed a separate measurement instrument alongside their normal\ngrading.\n'})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"SLIDE 6.7\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## The Srujana Pathway \u2014 Where This Fits Institutionally\n\nStage 1 \u2014 Knowledge, Skill, Attitude\nBuilt through curriculum, clubs, and self-learning\n\nStage 2 \u2014 Internships and Industry-Mentored Projects\n\nStage 3 \u2014 Solution Development\nResearch, consulting, product building\n\nStage 4 \u2014 AI-Era Careers\nEntrepreneurship, portfolio building, brand building\n\nThe course redesign work in this program feeds Stage 1. Its\noutputs \u2014 student portfolios, documented judgment, verified\ncapability \u2014 carry forward into Stages 2 through 4.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nThis slide connects individual classroom work to the institution's\nlarger strategic pathway \u2014 useful for faculty who want to see how\ntheir redesign effort contributes beyond their own course.\n"})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"SLIDE 6.8\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## Faculty Capstone: Redesign One Complete Course\n\nRequired deliverables:\n\n- Course Audit (using the Module 1 rubric)\n- AI Risk Analysis\n- AI Usage Policy for the course (Green / Yellow / Red zones stated)\n- Three Lovable Assignments\n- Two AI-Resistant or AI-Ready Assessments (with tiered verification\n  sketched, per Module 4)\n- Revised Rubric\n- Reflection Report\n- Implementation Plan\n\nCertification tiers:\n- Bronze \u2014 one example of each required type, awareness-level\n- Silver \u2014 full Capstone as specified above\n- Gold \u2014 Silver, plus measured student outcome data from a pilot run\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nThe tiered certification structure exists so faculty with limited\ntime can still complete a meaningful first step (Bronze) rather\nthan disengaging entirely when faced with the full Silver-level\nrequirement. Encourage peer-pod review of Capstone drafts before\nsubmission.\n"})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"SLIDE 6.9\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n## The AI Pedagogy Maturity Model\n\nLevel 1: Traditional \u2014 no AI consideration\nLevel 2: Digital \u2014 technology-enabled learning\nLevel 3: AI-Aware \u2014 faculty recognize AI-related challenges\nLevel 4: AI-Ready \u2014 assignments and assessments are redesigned\nLevel 5: AI-Native \u2014 human-AI collaboration is systematically\nembedded across curriculum, assessment, projects, and career\npreparation\n\nWhere is your course today? Where do you want it to be after\nthis Capstone?\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nUse this as a closing self-assessment exercise \u2014 have faculty mark\ntheir course's current level and their target level for the\nCapstone, on paper or a shared board, as a visible commitment\nbefore the program moves to the Pilot phase.\n"})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'SLIDE 6.10\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# Closing\n\n> "The goal is not to stop students from using AI. The goal is to\n>  design learning experiences that develop capabilities becoming\n>  more valuable because AI exists."\n\nYour Capstone course redesign begins now. Your peer pod, your\nCourse Audit rubric, and the AI-Ready Assignment Canvas are your\nstarting tools.\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFACILITATOR NOTES:\nClose by returning to the opening slide\'s one-word fears collected\nat the very start of Module 1 \u2014 revisit them here, module by\nmodule, and note which are now addressed by a concrete tool from\nthis program and which remain genuinely open. Ending on this honest\nnote is more credible than claiming every fear is fully resolved.\n'})}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h1,{id:"part-b-appendix--theoretical-foundations-for-learning",children:"PART B: APPENDIX \u2014 THEORETICAL FOUNDATIONS FOR LEARNING"}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"This appendix is written as a reference document, not as slides.\nIt provides the research grounding behind the frameworks used\nthroughout Modules 1\u20136, for facilitators and faculty who want to\nunderstand the mechanisms behind the tools, or who need to defend\nthe program's design choices to skeptical colleagues or\naccreditation reviewers."})}),"\n",(0,s.jsx)(n.h2,{id:"introduction",children:"Introduction"}),"\n",(0,s.jsx)(n.p,{children:"Every framework used in this certification program \u2014 LOVABLE, the\nTiered Verification Model, Shift Up and Left, the Course Audit \u2014 is\na practical simplification of one or more established bodies of\nresearch in learning science, motivation psychology, and assessment\ntheory. This appendix names those bodies of research explicitly,\nexplains their core claims in plain language, and states which part\nof the program each one supports. It also notes, honestly, where\na theory has limits or where its application in this program is a\nsimplification rather than a direct implementation."}),"\n",(0,s.jsxs)(n.p,{children:["The theories are grouped into two sets: those primarily concerned\nwith ",(0,s.jsx)(n.strong,{children:"motivation and engagement"})," (why students want to do\nsomething), and those primarily concerned with ",(0,s.jsx)(n.strong,{children:"learning and\nretention"})," (how understanding actually forms and lasts). Module 3\ndraws mainly on the first set; Modules 1, 2, 4, and 5 draw mainly\non the second."]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"part-1-motivation-and-engagement",children:"Part 1: Motivation and Engagement"}),"\n",(0,s.jsx)(n.h3,{id:"self-determination-theory-deci--ryan",children:"Self-Determination Theory (Deci & Ryan)"}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Core claim:"})," Human motivation is strongest and most durable when\nthree basic psychological needs are met: autonomy (a sense of\nchoice and ownership over one's actions), competence (a sense of\nbeing capable and improving), and relatedness (a sense of\nconnection to other people through the activity)."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Why it matters here:"})," This is the strongest theoretical anchor\nfor the LOVABLE framework. Learner Agency corresponds directly to\nautonomy. Build/Create paired with an achievable level of challenge\ncorresponds to competence. Authentic Audience and Voice correspond\nto relatedness \u2014 the sense that real people, not just a grader,\nwill encounter the work."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Where it applies in this program:"})," Module 3 (Designing Lovable\nAssignments), directly."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"A limitation to hold in mind:"}),' Self-Determination Theory explains\nwhy a task can feel motivating. It does not, by itself, guarantee\nthe task is teaching the right disciplinary content \u2014 that check is\nhandled separately in Module 3\'s "Note on Rigor" slide, and is a\nreminder that motivation theory and learning-outcome validity are\ntwo different concerns that both need attention.']}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h3,{id:"flow-theory-csikszentmihalyi",children:"Flow Theory (Csikszentmihalyi)"}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Core claim:"}),' People experience a state of deep, absorbed\nengagement \u2014 "flow" \u2014 when the challenge of a task closely matches\ntheir current skill level. Too easy, and the task produces boredom;\ntoo hard, and it produces anxiety. Flow requires clear goals and\nfast feedback on progress.']}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Why it matters here:"}),' Explains why hands-on Build/Create tasks\noften feel different from passive explanation tasks \u2014 a\nwell-pitched challenge level is part of what makes an assignment\n"lovable" rather than merely permitted. It also gives a diagnostic\nquestion faculty can ask when a LOVABLE assignment isn\'t landing:\nis it too easy (routine, disengaging) or too hard (overwhelming,\ndemotivating) for this particular cohort?']}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Where it applies in this program:"})," Module 3, as a design check\nalongside Self-Determination Theory."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"A limitation to hold in mind:"}),' Flow is highly individual \u2014 the\nsame task can be "flow" for one student and either boring or\noverwhelming for another in the same class. This is an argument for\nbuilding some choice or difficulty-scaling into LOVABLE assignments\nrather than assuming one fixed version suits an entire cohort.']}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h3,{id:"situated-learning-and-legitimate-peripheral-participation-lave--wenger",children:"Situated Learning and Legitimate Peripheral Participation (Lave & Wenger)"}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Core claim:"})," Learning is not primarily an individual, abstract\nprocess \u2014 it happens through participation in real communities of\npractice, working on real problems alongside more experienced\npractitioners, even if only at the periphery of that practice at\nfirst."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Why it matters here:"})," This is the theoretical grounding for both\nLocal Context and Authentic Audience in LOVABLE. An assignment\ngrounded in a real, nearby problem, reviewed or witnessed by a real\naudience, is closer to genuine situated practice than an abstracted\ntextbook exercise \u2014 even if the student is still a novice."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Where it applies in this program:"})," Module 3 (Local Context,\nAuthentic Audience), and indirectly Module 4's Context-Based\nassessment category (local interviews, community projects)."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"A limitation to hold in mind:"}),' True situated learning usually\ninvolves sustained participation over time, not a single\nassignment. A one-off "local context" task borrows the spirit of\nthis theory without fully realizing it \u2014 worth being honest about\nthis with faculty rather than overclaiming.']}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h3,{id:"interest-development-model-hidi--renninger",children:"Interest Development Model (Hidi & Renninger)"}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Core claim:"})," Interest develops in four phases: triggered\nsituational interest (a one-off spark), maintained situational\ninterest (sustained by external structure), emerging individual\ninterest (the learner begins voluntarily returning to the topic),\nand well-developed individual interest (a durable, self-sustaining\ninterest independent of the original trigger)."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Why it matters here:"}),' A single "lovable" assignment is, at best,\na trigger for situational interest. Whether it develops into lasting\nindividual interest depends on what happens afterward \u2014 follow-up\nopportunities, further choice, continued relevance. This model gives\nfaculty a way to think about LOVABLE assignments as a starting point\nacross a course or program, not a one-time event with guaranteed\nlasting effect.']}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Where it applies in this program:"})," Module 3, as a longer-term\nframing for why LOVABLE design should recur across a course rather\nthan appear once."]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"part-2-learning-memory-and-assessment-design",children:"Part 2: Learning, Memory, and Assessment Design"}),"\n",(0,s.jsx)(n.h3,{id:"cognitive-load-theory-sweller",children:"Cognitive Load Theory (Sweller)"}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Core claim:"})," Working memory is limited. Learning is impaired when\nunnecessary mental effort (extraneous load) crowds out the effort\nneeded to actually process new material (germane load). Well-designed\ninstruction manages this by reducing extraneous load and pacing\ngermane load appropriately."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Why it matters here:"})," Directly relevant to Module 2's prompt\nengineering and AI evaluation content. Faculty and students both\nface real cognitive load when learning to verify AI output \u2014 asking\nsomeone to evaluate accuracy, completeness, creativity, and\nreliability all at once, on unfamiliar material, is a real load\nmanagement problem. The four-part evaluation method in Module 2 is,\nin effect, a worked structure designed to reduce that load by giving\nevaluators a fixed checklist rather than an open-ended judgment call."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Where it applies in this program:"})," Module 2 (AI Evaluation,\nPrompt Engineering)."]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h3,{id:"retrieval-practice-roediger--karpicke",children:"Retrieval Practice (Roediger & Karpicke)"}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Core claim:"}),' Actively recalling information from memory \u2014\nrather than passively re-reading or re-reviewing it \u2014 produces\nstronger, more durable learning. This is sometimes called the\n"testing effect."']}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Why it matters here:"})," Directly relevant to Module 4's shift\ntoward viva and performance-based assessment. A viva, by its nature,\nrequires a student to retrieve and articulate understanding in real\ntime rather than recognize a correct answer on a page \u2014 this is a\nretrieval-practice-aligned format, which is part of why it also\ntends to reveal genuine understanding versus surface familiarity."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Where it applies in this program:"})," Module 4 (viva-based Tiers 2\nand 3 of the Tiered Verification Model)."]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h3,{id:"desirable-difficulties-bjork",children:"Desirable Difficulties (Bjork)"}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Core claim:"})," Certain kinds of difficulty during learning \u2014 ones\nthat feel effortful and slower in the moment \u2014 actually improve\nlong-term retention and transfer, compared to conditions that feel\nsmooth and easy at the time but produce weaker lasting learning.\nNot all difficulty is desirable; difficulty caused by poor\ninstructional design (confusion, unclear goals) is not the same as\ndifficulty caused by productive struggle."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Why it matters here:"})," Gives Module 4's rationale for\nprocess-based and performance-based assessment a firmer footing \u2014\nthese formats are often more effortful for students than a\nmultiple-choice exam, and that added effort, if it is the\n",(0,s.jsx)(n.em,{children:"productive"})," kind, is part of what makes the learning last. This\nalso gives faculty language to explain to students why a more\ndemanding assessment format is a deliberate pedagogical choice, not\nan arbitrary added burden."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Where it applies in this program:"})," Module 4, as the rationale\nfor choosing observation-, performance-, and process-based\nassessment over purely written formats."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"A limitation to hold in mind:"})," The difficulty has to be the right\nkind. A confusing or badly designed viva is not a desirable\ndifficulty \u2014 it is just an obstacle. This is one more argument for\nModule 4's emphasis on clear, published rubrics and transparent\nTier 3 trigger criteria: difficulty should come from the cognitive\ndemand of the task, not from ambiguity about what is expected."]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h3,{id:"metacognition-and-self-regulated-learning-flavell-zimmerman",children:"Metacognition and Self-Regulated Learning (Flavell; Zimmerman)"}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Core claim:"})," Learning improves when learners actively monitor\nand regulate their own understanding \u2014 planning their approach,\nmonitoring their progress, and evaluating their own output \u2014 rather\nthan only producing work for someone else to judge."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Why it matters here:"})," This is the direct grounding for Tier 1 of\nthe Tiered Verification Model (student self-assessment against the\nrubric before submission) and for the Visible Thinking / reflection\nelements built into the Capstone (reflection logs, the Mother of\nAll Assignments' documented thinking process). Requiring students to\nself-assess and document their own reasoning is not just an\nadministrative check \u2014 it is a direct exercise of metacognitive\nskill, which independently improves learning outcomes."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Where it applies in this program:"})," Module 4 (Tier 1\nself-assessment), Module 5 (Mother of All Assignments' documented\nthinking), Module 6 (reflection reports in the Capstone)."]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h3,{id:"transfer-of-learning",children:"Transfer of Learning"}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Core claim:"}),' Learning that occurs in one context does not\nautomatically apply in a different context. "Near transfer" (applying\na skill to a very similar new situation) is relatively common;\n"far transfer" (applying a skill to a substantially different\nsituation) is much harder to achieve and requires deliberate design\n\u2014 varied practice contexts, explicit comparison across situations,\nand abstraction of underlying principles rather than memorization\nof a single worked procedure.']}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Why it matters here:"})," Directly relevant to Module 1's Course\nAudit and Module 6's curriculum mapping. An assignment redesigned\nin one course does not automatically mean a student can apply the\nsame judgment in a different course or in the workplace \u2014 this is\nthe argument for why curriculum-level redesign (Module 6) matters\nbeyond individual assignment-level redesign (Modules 3\u20135), and why\nthe Shift Up and Left target zone (origination and judgment) is\npursued as a recurring pattern across a program, not a single\ncourse event."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Where it applies in this program:"})," Module 1 (Course Audit),\nModule 6 (Curriculum Mapping Exercise, whole-course and\nwhole-curriculum redesign rationale)."]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"summary-table-module-to-theory-cross-reference",children:"Summary Table: Module-to-Theory Cross-Reference"}),"\n",(0,s.jsxs)(n.table,{children:[(0,s.jsx)(n.thead,{children:(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.th,{children:"Module"}),(0,s.jsx)(n.th,{children:"Practice or Tool"}),(0,s.jsx)(n.th,{children:"Primary Theoretical Anchor(s)"})]})}),(0,s.jsxs)(n.tbody,{children:[(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Module 1"}),(0,s.jsx)(n.td,{children:"Course Audit, transfer across courses"}),(0,s.jsx)(n.td,{children:"Transfer of Learning"})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Module 2"}),(0,s.jsx)(n.td,{children:"AI Evaluation method, Prompt Engineering"}),(0,s.jsx)(n.td,{children:"Cognitive Load Theory"})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Module 3"}),(0,s.jsx)(n.td,{children:"LOVABLE Framework"}),(0,s.jsx)(n.td,{children:"Self-Determination Theory, Flow Theory, Situated Learning, Interest Development Model"})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Module 4"}),(0,s.jsx)(n.td,{children:"Viva-based Tiers 2/3"}),(0,s.jsx)(n.td,{children:"Retrieval Practice"})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Module 4"}),(0,s.jsx)(n.td,{children:"Performance/process-based assessment rationale"}),(0,s.jsx)(n.td,{children:"Desirable Difficulties"})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Module 4"}),(0,s.jsx)(n.td,{children:"Tier 1 self-assessment"}),(0,s.jsx)(n.td,{children:"Metacognition / Self-Regulated Learning"})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Module 5"}),(0,s.jsx)(n.td,{children:"Mother of All Assignments, documented thinking"}),(0,s.jsx)(n.td,{children:"Metacognition / Self-Regulated Learning"})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Module 6"}),(0,s.jsx)(n.td,{children:"Curriculum Mapping, whole-course redesign"}),(0,s.jsx)(n.td,{children:"Transfer of Learning"})]})]})]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"a-note-on-honest-use-of-theory",children:"A Note on Honest Use of Theory"}),"\n",(0,s.jsxs)(n.p,{children:["None of the frameworks in Modules 1\u20136 are direct, literal\nimplementations of the theories above \u2014 they are practical design\ntools inspired by and consistent with this research. Facilitators\nshould represent this relationship accurately: the theories explain\n",(0,s.jsx)(n.em,{children:"why"})," the practical tools are reasonable design choices, not that\nthe tools are validated interventions in their own right. Where a\ndepartment or reviewer asks for evidence of impact, the honest\nanswer is that the tools are theory-informed by design, and their\nactual effectiveness at REVA should be tracked through the Success\nMetrics and Capstone pilot data described in Module 6 \u2014 not assumed\nfrom the theory alone."]})]})}function h(e={}){const{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(c,{...e})}):c(e)}},8453(e,n,t){t.d(n,{R:()=>o,x:()=>r});var i=t(6540);const s={},a=i.createContext(s);function o(e){const n=i.useContext(a);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:o(e.components),i.createElement(a.Provider,{value:n},e.children)}}}]);